void need(bool b,const char* why){if(!b)throw std::runtime_error(why);}
QWidget* scroller(QWidget* widget,QWidget* parent){auto s=new QScrollArea(parent);s->setWidgetResizable(true);s->setFrameShape(QFrame::NoFrame);s->setWidget(widget);return s;}
QString json(QJsonValue value){return QString::fromUtf8(value.isArray()?QJsonDocument(value.toArray()).toJson(QJsonDocument::Indented):QJsonDocument(value.toObject()).toJson(QJsonDocument::Indented));}
qint64 epoch(QJsonValue value){auto at=QDateTime::fromString(value.toString(),Qt::ISODateWithMs);return at.isValid()?at.toMSecsSinceEpoch():-1;}
