NewsPage::~NewsPage(){cancel();workers.clear();workers.waitForDone();}
void NewsPage::guard(std::function<void()> action){try{action();}catch(const std::exception& e){state->setText(QString::fromUtf8(e.what()));}}
void NewsPage::clean()const{need(!dirty,"请保存或明确取消未保存人工备注");}
void NewsPage::controls(){cancelButton->setEnabled(busy);note->setEnabled(!busy);importText->setEnabled(!busy);for(auto w:QList<QWidget*>{scope,days,pages,identity,sector})w->setEnabled(!busy&&!dirty);bool linked=!selected.isEmpty()&&!selected["link"].isNull();readButton->setEnabled(!busy&&!dirty&&allowNetwork&&linked);openButton->setEnabled(!busy&&!dirty&&linked);}
void NewsPage::cancel(){++generation;cancelled->store(true);workers.clear();feed->cancel();busy=false;controls();}
void NewsPage::run(std::function<QJsonObject(const publicNews::Cancel&)> work,std::function<void(QJsonObject)> done){cancel();cancelled=std::make_shared<std::atomic_bool>(false);auto flag=cancelled;auto token=++generation;busy=true;controls();QPointer<NewsPage> self(this);workers.start([self,flag,token,work,done]{QJsonObject result;QString error;try{result=work([flag]{return flag->load();});}catch(const std::exception& e){error=QString::fromUtf8(e.what());}QMetaObject::invokeMethod(qApp,[self,flag,token,result,error,done]{if(!self||flag->load()||self->generation!=token)return;self->busy=false;if(error.isEmpty())self->guard([done,result]{done(result);});else self->state->setText("未完成："+error+"；原记录保留");self->controls();},Qt::QueuedConnection);});}
QJsonObject NewsPage::query()const{return publicNews::query(QStringList{"market","stock","sector","announcement"}[scope->currentIndex()],QList<int>{1,3,7,14}[days->currentIndex()],pages->currentIndex()+1,identity->text().trimmed(),sector->text().trimmed());}
QJsonObject NewsPage::archived(QString id)const{for(auto v:archive["items"].toArray())if(v.toObject()["id"]==id)return v.toObject();return {};}
QJsonObject NewsPage::find(QString id)const{auto saved=archived(id);if(archiveMode&&!saved.isEmpty())return saved;for(auto v:snapshot["items"].toArray())if(v.toObject()["id"]==id)return v.toObject();return saved;}
QString NewsPage::cacheStatus()const{return (archiveMode?QString("本机收藏/保存%1条").arg(archive["items"].toArray().size()):snapshot.isEmpty()?QString("当前范围无完整缓存"):QString("当前范围%1条 · 检查 %2").arg(snapshot["items"].toArray().size()).arg(snapshot["fetchedAt"].toString()))+"；仅明确请求页范围，不代表全网。统一发布时间未知。"+(attempt["error"].toString().isEmpty()?QString():"\n最近失败 "+attempt["checkedAt"].toString()+" "+attempt["error"].toString());}
void NewsPage::load(){if(dirty||busy)return;int priorPane=tabs->currentIndex();QJsonObject q;try{q=query();}catch(...){}QString path=file;run([path,q](auto cancel){publicNews::Store s(path);return QJsonObject{{"archive",s.archive(cancel)},{"cache",q.isEmpty()?QJsonObject{}:s.cache(q,cancel)}};},[this,priorPane](QJsonObject result){archive=result["archive"].toObject();auto cache=result["cache"].toObject();snapshot=cache["snapshot"].toObject();attempt=cache["attempt"].toObject();sources();render();QString id=savedNote.isEmpty()?restoreId:savedNote["id"].toString();if(!id.isEmpty()){auto found=find(id);if(!found.isEmpty()){choose(found);if(!savedNote.isEmpty()){rendering=true;note->setPlainText(savedNote["note"].toString());draftRevision=qint64(savedNote["revision"].toDouble());rendering=false;dirty=true;state->setText("未保存人工备注已恢复，未自动提交/联网");}restoreId.clear();savedNote={};}else{selected={};article={};}}rendering=true;tabs->setCurrentIndex(dirty?1:priorPane);rendering=false;if(!dirty)state->setText(cacheStatus());});}
void NewsPage::scopeChanged(){if(rendering)return;guard([this]{clean();cancel();snapshot={};attempt={};selected={};article={};offset=0;render();state->setText("范围变化；请明确读取本机缓存或刷新。人工档案保留。");});}
void NewsPage::sources(){QSignalBlocker blocker(source);QString previous=restoreSource.isEmpty()?source->currentText():restoreSource;QSet<QString> names;for(auto rows:{archive["items"].toArray(),snapshot["items"].toArray()})for(auto v:rows)names.insert(v.toObject()["source"].toString());auto sorted=names.values();std::sort(sorted.begin(),sorted.end());source->clear();source->addItem("全部来源");source->addItems(sorted);source->setCurrentIndex(qMax(0,source->findText(previous)));restoreSource.clear();}
void NewsPage::render(){if(rendering)return;rendering=true;list->setRowCount(0);guard([this]{QList<QJsonObject> rows;auto input=archiveMode?archive["items"].toArray():snapshot["items"].toArray();QString needle=search->text().trimmed(),target=identity->text().section(':',2,2),sectorTarget=sector->text().trimmed();if(!QRegularExpression("^(SH|SZ|BJ):stock:[0-9]{6}$").match(identity->text()).hasMatch())target.clear();auto now=QDateTime::currentDateTimeUtc();int daysLimit=QList<int>{1,3,7,14}[days->currentIndex()];for(auto v:input){auto r=v.toObject(),saved=archived(r["id"].toString());if(!saved.isEmpty())for(auto key:{"favorite","saved","note"})r[key]=saved[key];auto priority=publicNews::priority(r,now),relevance=publicNews::relevance(r,target,sectorTarget,needle);r["priorityView"]=priority;r["relevanceView"]=relevance;if(!archiveMode&&!r["publishedAt"].isNull()&&epoch(r["publishedAt"])<now.addDays(-daysLimit).toMSecsSinceEpoch())continue;if(scope->currentIndex()==3&&r["type"]!="announcement")continue;if(!archiveMode&&scope->currentIndex()==1&&(target.isEmpty()||publicNews::relevance(r,target,{}, {})["score"].toInt()==0))continue;if(!archiveMode&&scope->currentIndex()==2&&!sectorTarget.isEmpty()&&publicNews::relevance(r,{},sectorTarget,{})["score"].toInt()==0)continue;if(source->currentIndex()>0&&r["source"]!=source->currentText())continue;int mode=libraryFilter->currentIndex();if((mode==1&&!r["favorite"].toBool())||(mode==2&&!r["saved"].toBool())||(mode==3&&priority["score"].toInt()<60)||(mode==4&&r["type"]!="announcement"))continue;QString searchable=r["title"].toString()+" "+r["summary"].toString()+" "+r["source"].toString()+json(r["relatedStocks"])+json(r["relatedSectors"]);if(!searchable.contains(needle,Qt::CaseInsensitive))continue;rows<<r;}int sortBy=sort->currentIndex();std::stable_sort(rows.begin(),rows.end(),[sortBy](auto a,auto b){double x=sortBy==1?a["relevanceView"].toObject()["score"].toDouble(-1):sortBy==2?a["priorityView"].toObject()["score"].toDouble(-1):double(epoch(a["publishedAt"]));double y=sortBy==1?b["relevanceView"].toObject()["score"].toDouble(-1):sortBy==2?b["priorityView"].toObject()["score"].toDouble(-1):double(epoch(b["publishedAt"]));return x==y?a["id"].toString()<b["id"].toString():x>y;});total=rows.size();if(offset>=total)offset=qMax(0,(total-1)/20*20);for(int i=offset;i<qMin(total,offset+20);i++){auto r=rows[i];int row=list->rowCount();list->insertRow(row);QStringList cells{r["title"].toString(),r["source"].toString()+" · "+r["provider"].toString(),r["publishedAt"].isNull()?"未知，不能用检查时间代替":r["publishedAt"].toString(),QString::number(r["priorityView"].toObject()["score"].toInt()),(r["favorite"].toBool()?QString("★ 收藏 · "):QString())+(r["saved"].toBool()?"已保存":"未保存")};for(int k=0;k<cells.size();k++){auto cell=new QTableWidgetItem(cells[k]);cell->setToolTip(cells[k]);list->setItem(row,k,cell);}list->item(row,0)->setData(Qt::UserRole,r);if(r["id"]==selected["id"])list->selectRow(row);}});rendering=false;controls();}
void NewsPage::choose(){clean();int index=list->currentRow();if(index<0)return;choose(list->item(index,0)->data(Qt::UserRole).toJsonObject());}
void NewsPage::choose(QJsonObject r){clean();selected=publicNews::item(r);auto saved=archived(selected["id"].toString());if(!saved.isEmpty())for(auto key:{"favorite","saved","note"})selected[key]=saved[key];article=saved["article"].toObject();articleAttempt={};rendering=true;note->setPlainText(selected["note"].toString());tabs->setCurrentIndex(1);rendering=false;dirty=false;displayArticle();QString path=file,id=selected["id"].toString();auto frozen=selected;run([path,frozen](auto cancel){return publicNews::Store(path).article(frozen,cancel);},[this,id](QJsonObject result){if(selected["id"]!=id)return;if(result["article"].isObject())article=result["article"].toObject();articleAttempt=result["attempt"].toObject();displayArticle();state->setText("本机原文缓存已读；尚未请求网络");});}
void NewsPage::displayArticle(){if(selected.isEmpty())return;auto priority=publicNews::priority(selected,QDateTime::currentDateTimeUtc()),relevance=publicNews::relevance(selected,identity->text().section(':',2,2),sector->text(),search->text());heading->setText(selected["title"].toString()+"\n"+selected["source"].toString()+" · 经 "+selected["provider"].toString()+"\n源时间 "+(selected["publishedAt"].isNull()?"未知，原字段 "+selected["timeRaw"].toString():selected["publishedAt"].toString())+" · "+selected["timeProvenance"].toString()+"\n原文 "+(selected["link"].isNull()?"无有效链接":selected["link"].toString()));QString text="摘要（独立，不是全文）\n"+(selected["summary"].toString().isEmpty()?QString("来源未提供摘要"):selected["summary"].toString());if(article["status"]=="available"){QString full="可读公开/存档正文段落\n";for(auto p:article["paragraphs"].toArray())full+=p.toString()+"\n\n";text=full+"\n独立摘要\n"+selected["summary"].toString();bodyStatus->setText("已存正文 · 读取 "+article["fetchedAt"].toString()+" · "+article["origin"].toString()+" · "+article["message"].toString()+(articleAttempt["error"].toString().isEmpty()?QString():"\n旧正文保留；最近失败 "+articleAttempt["checkedAt"].toString()+" "+articleAttempt["error"].toString()));}else bodyStatus->setText("正文未取得；摘要不是全文 · "+article["message"].toString()+(articleAttempt.isEmpty()?QString():"\n最近尝试 "+articleAttempt["checkedAt"].toString()+" "+articleAttempt["error"].toString()));body->setPlainText(text);scoreInfo->setPlainText("本地研究优先级 "+QString::number(priority["score"].toInt())+"/100（非源站推荐）\n"+json(priority["reasons"])+"\n本地相关性 "+(relevance["score"].isNull()?QString("未提供目标"):QString::number(relevance["score"].toInt()))+"\n"+json(relevance["matches"])+"\n原关联来源 "+json(selected["associationProvenance"])+(selected["image"].isObject()?"\n上游图片元数据（未下载/未验证许可）："+json(selected["image"]):"\n上游未提供图片"));controls();}
void NewsPage::refresh(){clean();need(allowNetwork,"当前运行未启用网络");auto q=query();cancel();busy=true;controls();state->setText("明确读取2栏目×指定1–3页；12秒总期限，不自动抓全网");need(feed->start(q),"已有来源任务进行中");}
void NewsPage::readArticle(){clean();need(allowNetwork&&!selected.isEmpty()&&!selected["link"].isNull(),"未启用网络或当前项没有原文链接");cancel();requestedItem=selected;busy=true;controls();state->setText("只读取当前固定白名单原文；12秒期限，无登录/拒绝绕过");need(feed->readArticle(requestedItem),"已有来源任务进行中");}
